:root {

  /* Farby */
  --color-primary:     #7361FF;
  --color-primary-dark:#5B4DD6;
  --color-primary-bg:  #EDE9FF;
  --color-text:        #111827;
  --color-muted:       #6B7280;
  --color-border:      #E5E7EB;
  --color-surface:     #FFFFFF;
  --color-bg:          #F7F7FB;

  /* Typografia */
  --font-base:  'Arial', sans-serif;
  --fs-xs:   12px;
  --fs-sm:   14px;
  --fs-base: 16px;
  --fs-lg:   20px;
  --fs-xl:   28px;
  --fw-normal: 400;
  --fw-bold:   700;
  --fw-black:  900;

  /* Spacing */
  --space-xs:  4px;
  --space-sm:  8px;
  --space-md:  16px;
  --space-lg:  24px;
  --space-xl:  40px;

  /* Radius */
  --radius-sm:  8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 100px;

  /* Tiene */
  --shadow-sm: 0 2px 8px rgba(115,97,255,0.08);
  --shadow-md: 0 4px 20px rgba(115,97,255,0.15);
}

*, *::before, *::after {
